WITH valid AS (SELECT *, WEEKOFYEAR(paid_at) AS paid_at_weekofyear, COALESCE(method, 'DIRECT') AS method_clean FROM payments WHERE order_id IS NOT NULL) SELECT DATE_TRUNC('YEAR', paid_at) AS year_start, CASE WHEN amount >= 1710 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, DATE_TRUNC('QUARTER', paid_at) AS quarter_start, MAX(amount) FILTER (WHERE status = 'REFUNDED') AS refunded_max_amount, MAX(paid_at) AS ended_at, COUNT_IF(method = 'cash') AS cash_events, SUM(CASE WHEN method = 'bank_transfer' THEN paid_at_weekofyear ELSE 0 END) AS bank_transfer_paid_at_weekofyear, GROUPING(DATE_TRUNC('YEAR', paid_at)) AS gid FROM valid GROUP BY GROUPING SETS ((DATE_TRUNC('YEAR', paid_at), CASE WHEN amount >= 1710 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('QUARTER', paid_at)), (DATE_TRUNC('YEAR', paid_at), CASE WHEN amount >= 1710 THEN 'PREMIUM' ELSE 'STANDARD' END), (DATE_TRUNC('YEAR', paid_at)));
